-- ============================================================
-- 408 体检套餐明细改为引用项目目录（含项目目录补项与存量 16 套餐重排）
-- 日期：2026-11-27
-- 背景：体检套餐明细原来是自由文本（item_name 手填 + amount 手填），与检验/检查/诊疗项目
--       目录无关联，套餐里"项目是什么"没有可维护来源，价格也与价表脱节。
-- 内容：
--   1) sys_checkup_package_item / biz_checkup_result 增加 item_source / item_id / item_code 三列，
--      明细改为「引用目录项目」，名称、编码、价格、参考范围以目录为准。
--   2) 项目目录补 24 项体检常用项目（检验 8、检查 5、一般检查 11，见下）；编码统一取 9xx 体检专用段
--      （LB901~ / US902~ / TR901~ 与既有 TR116~TR120），避开各表常规号段，防止与并行补项撞码。
--      一般检查（身高体重腰围血压、内外眼科口腔耳鼻喉妇科、认知/营养/跌倒评估）落在诊疗项目
--      sys_treatment_item，不另建第四套目录。
--   3) 存量 16 个套餐 174 条自由文本明细按名称映射到目录编码后重排（同单重复项目合并），
--      明细金额一律取目录价格，套餐价重算为明细合计。
-- 口径：
--   item_source 1-检验(sys_laboratory_item) 2-检查(sys_inspection_item) 3-一般检查(sys_treatment_item)；
--   套餐分项 item_type 与 item_source 一一对应（1-检验 2-检查 3-一般）。
-- 幂等：ALTER 走 information_schema 判重；字典与明细按主键 INSERT ... ON DUPLICATE KEY UPDATE 全字段覆盖；
--       明细 item_id 由尾部 UPDATE ... JOIN 按 item_code 回填（重放自动纠偏）；旧明细软删、套餐价重算可重复执行。
-- 回滚：见 408-回滚.sql
-- ============================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- ---------- 一、表结构：明细加来源/目录项目ID/编码 ----------
-- sys_checkup_package_item.item_source
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `sys_checkup_package_item` ADD COLUMN `item_source` tinyint NULL COMMENT ''项目来源（1-检验项目 2-检查项目 3-一般检查）'' AFTER `package_id`',
       'DO 0') FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'sys_checkup_package_item' AND COLUMN_NAME = 'item_source');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- sys_checkup_package_item.item_id
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `sys_checkup_package_item` ADD COLUMN `item_id` bigint NULL COMMENT ''来源目录项目ID'' AFTER `item_source`',
       'DO 0') FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'sys_checkup_package_item' AND COLUMN_NAME = 'item_id');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- sys_checkup_package_item.item_code
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `sys_checkup_package_item` ADD COLUMN `item_code` varchar(32) NULL COMMENT ''来源目录项目编码'' AFTER `item_id`',
       'DO 0') FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'sys_checkup_package_item' AND COLUMN_NAME = 'item_code');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- biz_checkup_result.item_source
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `biz_checkup_result` ADD COLUMN `item_source` tinyint NULL COMMENT ''项目来源（1-检验项目 2-检查项目 3-一般检查）'' AFTER `record_id`',
       'DO 0') FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'biz_checkup_result' AND COLUMN_NAME = 'item_source');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- biz_checkup_result.item_id
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `biz_checkup_result` ADD COLUMN `item_id` bigint NULL COMMENT ''来源目录项目ID'' AFTER `item_source`',
       'DO 0') FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'biz_checkup_result' AND COLUMN_NAME = 'item_id');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- biz_checkup_result.item_code
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `biz_checkup_result` ADD COLUMN `item_code` varchar(32) NULL COMMENT ''来源目录项目编码'' AFTER `item_id`',
       'DO 0') FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'biz_checkup_result' AND COLUMN_NAME = 'item_code');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- ---------- 二、项目目录补项（体检常用项，编码 9xx 段） ----------
-- 检验项目 8 项
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 检查项目 5 项
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 一般检查（诊疗项目）11 项
ON DUPLICATE KEY UPDATE `id` = `id`;

-- ---------- 三、存量明细软删（原 174 行自由文本明细留档） ----------
UPDATE `sys_checkup_package_item` SET `del_flag` = 1
 WHERE `id` IN (2350000000000000511, 2350000000000000512, 2350000000000000513, 2350000000000000514, 2350000000000000515, 2350000000000000516, 2350000000000000517, 2350000000000000518, 2350000000000000519, 2350000000000000520, 2350000000000000521, 2350000000000000522, 2350000000000000523, 2350000000000000524, 2350000000000000525, 2350000000000000526, 2350000000000000527, 2350000000000000528, 2350000000000000529, 2350000000000000530, 2350000000000000531, 2350000000000000532, 2350000000000000533, 2350000000000000534, 2350000000000000535, 2350000000000000536, 2350000000000000537, 2350000000000000538, 2350000000000000539, 2350000000000000540, 2350000000000000541, 2350000000000000542, 2350000000000000543, 2350000000000000544, 2350000000000000545, 2350000000000000546, 2350000000000000547, 2350000000000000548, 2350000000000000549, 2350000000000000550, 2350000000000000551, 2350000000000000552, 2350000000000000553, 2350000000000000554, 2350000000000000555, 2350000000000000556, 2350000000000000557, 2350000000000000558, 2350000000000000559, 2350000000000000560, 2350000000000000561, 2350000000000000562, 2350000000000000563, 2350000000000000564, 2350000000000000565, 2350000000000000566, 2350000000000000567, 2350000000000000568, 2350000000000000569, 2350000000000000570, 2350000000000000571, 2350000000000000701, 2350000000000000702, 2350000000000000703, 2350000000000000704, 2350000000000000705, 2350000000000000706, 2350000000000000707, 2350000000000000708, 2350000000000000709, 2350000000000000710, 2350000000000000711, 2350000000000000712, 2350000000000000713, 2350000000000000714, 2350000000000000715, 2350000000000000716, 2350000000000000717, 2350000000000000718, 2350000000000000719, 2350000000000000720, 2350000000000000721, 2350000000000000722, 2350000000000000723, 2350000000000000724, 2350000000000000725, 2350000000000000726, 2350000000000000727, 2350000000000000728, 2350000000000000729, 2350000000000000730, 2350000000000000731, 2350000000000000732, 2350000000000000733, 2350000000000000734, 2350000000000000735, 2350000000000000736, 2350000000000000737, 2350000000000000738, 2350000000000000739, 2350000000000000740, 2350000000000000741, 2350000000000000742, 2350000000000000743, 2350000000000000744, 2350000000000000745, 2350000000000000746, 2350000000000000747, 2350000000000000748, 2350000000000000749, 2350000000000000750, 2350000000000000751, 2350000000000000752, 2350000000000000753, 2350000000000000754, 2350000000000000755, 2350000000000000756, 2350000000000000757, 2350000000000000758, 2350000000000000759, 2350000000000000760, 2350000000000000761, 2350000000000000762, 2350000000000000763, 2350000000000000764, 2350000000000000765, 2350000000000000766, 2350000000000000767, 2350000000000000768, 2350000000000000769, 2350000000000000770, 2350000000000000771, 2350000000000000772, 2350000000000000773, 2350000000000000774, 2350000000000000775, 2350000000000000776, 2350000000000000777, 2350000000000000778, 2350000000000000779, 2350000000000000780, 2350000000000000781, 2350000000000000782, 2350000000000000783, 2350000000000000784, 2350000000000000785, 2350000000000000786, 2350000000000000787, 2350000000000000788, 2350000000000000789, 2350000000000000790, 2350000000000000791, 2350000000000000792, 2350000000000000793, 2350000000000000794, 2350000000000000795, 2350000000000000796, 2350000000000000797, 2350000000000000798, 2350000000000000799, 2350000000000000800, 2350000000000000801, 2350000000000000802, 2350000000000000803, 2350000000000000804, 2350000000000000805, 2350000000000000806, 2350000000000000807, 2350000000000000808, 2350000000000000809, 2350000000000000810, 2350000000000000811, 2350000000000000812, 2350000000000000813);

-- ---------- 四、按目录重排明细（173 行；item_id 留待下一步回填） ----------
ON DUPLICATE KEY UPDATE
  `item_source` = VALUES(`item_source`), `item_id` = VALUES(`item_id`), `item_code` = VALUES(`item_code`),
  `item_name` = VALUES(`item_name`), `item_type` = VALUES(`item_type`), `ref_standard` = VALUES(`ref_standard`),
  `amount` = VALUES(`amount`), `sort_order` = VALUES(`sort_order`), `del_flag` = 0;

-- ---------- 五、明细 item_id 按编码回填目录真实 ID（重放即纠偏） ----------
UPDATE `sys_checkup_package_item` i JOIN `sys_laboratory_item` d
   ON d.item_code = i.item_code AND d.del_flag = 0 AND d.status = 1
   SET i.item_id = d.id WHERE i.item_source = 1 AND i.del_flag = 0;

UPDATE `sys_checkup_package_item` i JOIN `sys_inspection_item` d
   ON d.item_code = i.item_code AND d.del_flag = 0 AND d.status = 1
   SET i.item_id = d.id WHERE i.item_source = 2 AND i.del_flag = 0;

UPDATE `sys_checkup_package_item` i JOIN `sys_treatment_item` d
   ON d.item_code = i.item_code AND d.del_flag = 0 AND d.status = 1
   SET i.item_id = d.id WHERE i.item_source = 3 AND i.del_flag = 0;

-- ---------- 六、套餐价 = 明细合计 ----------
UPDATE sys_checkup_package SET price = '371.00' WHERE id = 2350000000000000501;
UPDATE sys_checkup_package SET price = '521.00' WHERE id = 2350000000000000502;
